"""100 additional original practice questions for profile ЕГЭ; no DB changes."""
from fractions import Fraction
from math import gcd
TASKS=[]
def add(n,k,title,body,ans,solution,diagram=None):
    TASKS.append(dict(key=f'plus-{n:02}-{k:02}',num=n,title=title,body=body,
      answer=None if ans is None else str(ans),solution=solution,
      difficulty='повышенный' if n<=12 else 'сложный',diagram=diagram))
# 60 short-answer tasks, five for each number. Varied methods, exact checked answers.
for k in range(1,6):
    a=2*k+3; b=k+2
    add(1,k,'Треугольник и площадь',f'В треугольнике основание равно {2*a}, высота к нему равна {b}. Найдите площадь.',a*b,f'S=(1/2)·{2*a}·{b}={a*b}.','triangle')
    add(2,k,'Окружность и центральный угол',f'Радиус окружности равен {2*k+2}. Найдите длину дуги, соответствующей центральному углу 90°, делённую на π.',k+1,f'Длина четверти окружности равна 2πR/4=π·{k+1}. Поэтому ответ {k+1}.','circle')
    add(3,k,'Объём прямой призмы',f'Площадь основания прямой призмы равна {3*k+5}, высота {k+3}. Найдите объём.',(3*k+5)*(k+3),f'V=Sосн·h=({3*k+5})·({k+3})={(3*k+5)*(k+3)}.','cube')
    add(4,k,'Вероятность без возвращения',f'В ящике {k+3} красных и {k+3} синих шаров. Случайно извлекают два шара без возвращения. Найдите вероятность того, что они разных цветов. Ответ округлите до сотых.', f'{round((k+3)/(2*k+5),2):.2f}',f'P=2·({k+3}/{2*k+6})·({k+3}/{2*k+5})={(k+3)/(2*k+5):.6f}. Округление до сотых: {round((k+3)/(2*k+5),2):.2f}.')
    add(5,k,'Вероятность независимых событий',f'Два стрелка независимо попадают с вероятностями {k+2}/10 и 1/2 соответственно. Найдите вероятность, что попадёт ровно один стрелок.',0.5,f'P=p·(1−1/2)+(1−p)·1/2=1/2. Ответ 0,5.')
    add(6,k,'Логарифмическое уравнение',f'Решите уравнение log₂(x−{k}) = {k+1}.',k+2**(k+1),f'x−{k}=2^{k+1}={2**(k+1)}, x={k+2**(k+1)}. ОДЗ x>{k} выполнено.')
    add(7,k,'Производная в точке',f'f(x)={k+1}x³−{2*k}x²+{k+4}x. Найдите f′(1).',3*(k+1)-4*k+(k+4),f'f′(x)={3*(k+1)}x²−{4*k}x+{k+4}. При x=1 получаем {3*(k+1)-4*k+(k+4)}.')
    add(8,k,'Движение навстречу',f'Два велосипедиста выехали навстречу со скоростями {12+k} и {14+k} км/ч. Расстояние {2*(26+2*k)} км. Через сколько часов встретятся?',2,f'Скорость сближения {26+2*k} км/ч, время {2*(26+2*k)}/{26+2*k}=2 ч.')
    add(9,k,'Алгебраическое преобразование',f'Найдите значение (a²−b²)/(a−b) при a={3*k+8}, b={k+1}.',4*k+9,f'(a²−b²)/(a−b)=a+b={3*k+8}+{k+1}={4*k+9}, поскольку a≠b.')
    add(10,k,'Геометрическая прогрессия',f'Первый член геометрической прогрессии равен {k+1}, знаменатель 2. Найдите четвёртый член.',8*(k+1),f'b₄=b₁·q³={k+1}·8={8*(k+1)}.')
    add(11,k,'Показательное уравнение',f'Решите уравнение 5^(x−{k})=125.',k+3,f'125=5³, следовательно x−{k}=3 и x={k+3}.')
    add(12,k,'Наибольшее значение квадратичной функции',f'Найдите наибольшее значение f(x)=−(x−{k})²+{3*k+8} на отрезке [{k-2};{k+3}].',3*k+8,f'Квадрат неотрицателен, вершина x={k} принадлежит отрезку; максимум {3*k+8}.')
# 40 written-answer tasks: 5 per 13..19 plus one extra on 13,14,17,18,19.
for k in range(1,6):
    q=k+1
    add(13,k,'Тригонометрическое уравнение',f'Решите уравнение 2sin²x−3sin x+1=0. Сколько корней на отрезке [2π·{k}; 2π·{k+1}]?',None,'t=sin x; (2t−1)(t−1)=0. На любом полном периоде корни x=π/6+2πn, 5π/6+2πn, π/2+2πn. Концы периода корнями не являются, значит ровно 3 корня.','trig')
    a=2*k+4
    add(14,k,'Стереометрия: куб и диагональ',f'В кубе с ребром {a} найдите квадрат длины пространственной диагонали и угол между этой диагональю и плоскостью основания.',None,f'Длина диагонали d={a}√3, следовательно d²={3*a*a}. Проекция диагонали на основание — диагональ грани {a}√2, tan угла=1/√2, угол arctan(1/√2).','cube')
    add(15,k,'Показательное неравенство',f'Решите неравенство 2^(2x)−{(2**k)+(2**(k+2))}·2^x+{2**(2*k+2)}≤0.',None,f'Обозначим t=2^x>0. Квадратный трёхчлен равен (t−{2**k})(t−{2**(k+2)}), поэтому {2**k}≤t≤{2**(k+2)}. Ответ x∈[{k};{k+2}].','algebra')
    principal=10000*(k+4)
    add(16,k,'Кредит с процентами',f'Взят кредит {principal} рублей под 10% годовых. Долг погашают двумя равными годовыми платежами, начисляя проценты перед каждым платежом. Найдите размер платежа.',None,f'Пусть A — платёж. 0=1,1(1,1·{principal}−A)−A, поэтому A=1,21·{principal}/2,1={principal}·121/210 рублей (точное дробное значение).','finance')
    p=k+2; r=k+8
    add(17,k,'Планиметрия: касательная и секущая',f'Из точки P проведены касательная PT и секущая PAB. PA={p*p}, PB={r*r}. Найдите PT и докажите используемую формулу.',None,f'По подобию треугольников PT²=PA·PB={p*p}·{r*r}, PT={p*r}. Формула следует из равенства углов между касательной и хордой и вписанных углов.','circle')
    add(18,k,'Параметр и количество корней',f'При каких действительных a уравнение x²−2ax+{k*k}=0 имеет ровно один действительный корень?',None,f'D=4a²−4·{k*k}=4(a²−{k*k}). Единственный корень при D=0, то есть a=±{k}.','algebra')
    add(19,k,'Числа и остатки',f'Найдите наименьшее положительное целое число n, которое делится на {2*k+2} и {3*k+3}, и обоснуйте минимальность.',None,f'НОК({2*k+2},{3*k+3})=6·{k+1}={6*(k+1)}. Любое число, делящееся на оба, кратно НОК, поэтому оно не меньше {6*(k+1)}.','numbers')
# five further unusual tasks, including proof and geometry
add(13,6,'Отбор корней по окружности','Решите sin(2x)=0,5 и отберите корни на [0;π].',None,'2x=π/6+2πn или 5π/6+2πn. Тогда x=π/12+πn или 5π/12+πn. На [0;π] остаются π/12 и 5π/12.','trig')
add(14,6,'Сечение куба','Куб имеет ребро 8. Через середины трёх рёбер, исходящих из одной вершины, проведена плоскость. Найдите площадь треугольника сечения.',None,'Середины рёбер: (4,0,0),(0,4,0),(0,0,4). Сторона сечения равна 4√2, треугольник равносторонний. Площадь=(4√2)²√3/4=8√3.','cube')
add(17,6,'Высота к гипотенузе','Высота прямоугольного треугольника делит гипотенузу на отрезки 16 и 25. Найдите высоту, площадь и докажите формулу h²=pq.',None,'Из подобия двух малых прямоугольных треугольников h/p=q/h, значит h²=pq. h=√(16·25)=20, гипотенуза 41, S=41·20/2=410.','triangle')
add(18,6,'Квадратичная функция с параметром','Найдите все a, при которых уравнение x²−2(a+1)x+(a²−1)=0 имеет два различных положительных корня.',None,'D=4[(a+1)²−(a²−1)]=8(a+1)>0 => a>−1. Сумма корней 2(a+1)>0; произведение a²−1>0 => a<−1 либо a>1. Вместе получаем a>1.','algebra')
add(19,6,'Диофантово уравнение','Найдите все пары положительных целых (x,y), удовлетворяющие xy=x+y+3.',None,'Переносим: (x−1)(y−1)=4. Положительные делители 4 дают (x−1,y−1)=(1,4),(2,2),(4,1); ответ (2,5),(3,3),(5,2).','numbers')
assert len(TASKS)==100,len(TASKS)
assert len({t['key'] for t in TASKS})==100
